negativeExample:
class Example {
    // This should NOT be changed (field, not local)
    java.lang.StringBuffer fieldBuf = new java.lang.StringBuffer();

    // This should NOT be changed (method parameter, not local)
    void process(java.lang.StringBuffer paramBuf) {
        paramBuf.append("Processed");
    }

    // This should NOT be changed (return value, not local)
    java.lang.StringBuffer createBuf() {
        return new java.lang.StringBuffer();
    }

    // Thread-shared scenario, should not be changed by this rule
    private static java.lang.StringBuffer sharedBuffer = new java.lang.StringBuffer();
    void appendToShared(String text) {
        synchronized (sharedBuffer) {
            sharedBuffer.append(text);
        }
    }
}
